def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        # Create a wrapper function that keeps track of the most frequently used items
        class CacheWrapper:
            def __init__(self, maxsize, typed):
                self.most_frequently_used = []
                self.cache = {}
                self.maxsize = maxsize
                self.typed = typed

            def wrap(self, *args):
                # Return the cached result if it exists
                if args in self.cache:
                    self.most_frequently_used.append(args)
                    return self.cache[args]
                # Else, call the original function, cache the result, and return it
                else:
                    result = func(*args)
                    self.cache[args] = result
                    self.most_frequently_used.append(args)
                    return result

            def evict(self):
                # Remove the least frequently used item from the cache
                least_frequently_used = self.most_frequently_used.pop()
                del self.cache[least_frequently_used]

        # Wrap the function with the LFU cache wrapper
        cache_wrapper = CacheWrapper(maxsize, typed)
        return cache_wrapper.wrap

    return decorator

