def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorating_function(user_function):
        @wraps(user_function)
        def wrapper(*args, **kwargs):
            key = key(*args, **kwargs)
            lock.acquire()
            try:
                cache_value = cache[key]
            except KeyError:
                cache_value = user_function(*args, **kwargs)
                cache[key] = cache_value
            finally:
                lock.release()
            return cache_value
        return wrapper
    return decorating_function

class cachedmethod(object):

    def __init__(self, cache, key=hashkey, lock=None):
        self.cache = cache
        self.key = key
        self.lock = lock

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = self.key(args, kwargs)
            with self.lock:
                if key not in self.cache:
                    self.cache[key] = func(*args, **kwargs)
                return self.cache[key]
        return wrapper

def cachedmethod(self, cache, key=hashkey, lock=None):
        """Decorator to wrap a class or instance method with a memoizing
        callable that saves results in a cache.

        """

        if lock is None:
            lock = _Lock()

        if not callable(cache):
            cache = {}

        def _cached(*args, **kwargs):
            with lock:
                if key is None:
                    H = hash(frozenset(kwargs.items()))
                else:
                    H = key(args, kwargs)

                try:
                    val = cache[H]
                except KeyError:
                    cache[H] = val = f(self, *args, **kwargs)
                return val

        return wraps(f)(_cached)

def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(method):
        @wraps(method)
        def wrapper(*args, **kwargs):
            with lock:
                cache_key = key(*args, **kwargs)
                if cache_key in cache:
                    return cache[cache_key]
                result = method(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

