def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # create a dictionary of base classes and their indexes
    baseClasses = {c: i for i, c in enumerate(classes)}
    # sort the bases by their index
    bases = sorted(baseClasses, key=baseClasses.get)
    # iterate over the bases and check if any of them are not in the sorted list
    for i, base in enumerate(bases):
        if base not in bases[i+1:]:
            # if we find a base that is not in the sorted list, return the previous bases
            return bases[:i+1]
    # if we reach this point, all bases were in the sorted list, so return the entire list
    return bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
            for base in cls.__bases__:
                if base not in bases:
                    bases = minimalBases(base.mro())
    return bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        try:
            for cls_b in cls.__bases__:
                if cls_b not in bases:
                    bases.append(cls_b)
        except TypeError:
            pass
    return sorted(bases, key=lambda x: x.__name__)

