def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if isinstance(sequence, list):
        normalized = []
        for item in sequence:
            if isinstance(item, list):
                normalized.extend(_normalizeargs(item))
            elif isinstance(item, tuple):
                normalized.append(item)
            elif isinstance(item, _Interfaces):
                normalized.append(item)
            else:
                normalized.append(item)
        return normalized
    else:
        return _normalizeargs([sequence])

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not output:
        output = []
    for arg in sequence:
        if isinstance(arg, Declaration):
            output.append(arg)
        elif isinstance(arg, tuple):
            for item in arg:
                if isinstance(item, Declaration):
                    output.append(item)
                elif isinstance(item, tuple):
                    for subitem in item:
                        if isinstance(subitem, Declaration):
                            output.append(subitem)
        elif isinstance(arg, Interface):
            for meth in arg.methods:
                output.append(meth)
        else:
            raise ValueError("Invalid argument: " + str(arg))
    return output

def _normalize_args(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not output:
        output = []
    for item in sequence:
        if is_declarion(item):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(_normalize_args(item, output))
        elif is_interface(item):
            output.append(item)
        else:
            raise ValueError(f"Unsupported argument {item}")
    return output

def _normalizeargs(sequence, output=None):
    normalized_sequence = []
    for arg in sequence:
        if isinstance(arg, Declaration):
            normalized_sequence.append(arg)
        elif isinstance(arg, tuple):
            normalized_sequence.append(arg)
        elif isinstance(arg, Interface):
            normalized_sequence.append(arg)
        else:
            normalized_sequence.extend(arg._normalizeargs(output=output))
    return normalized_sequence

