def difference(d1, d2, level=-1):
    """Return a dictionary with items from `d1` not contained in `d2`.

    `level` sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in `d1` and `d2` but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    `d1` and `d2` remain unchanged. However, `d1` or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument `level`.
    """


    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value

        elif level < 0:
            pass

        elif isinstance(value, dict):
            subm = difference(value, d2[key], level - 1)
            if subm:
                result[key] = subm

        elif value != d2[key]:
            result[key] = value

    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    result = {}
    for key, value in d1.items():
        if key in d2:
            if level == -1:
                # continue recursion as long as possible, ignore type differences
                continue
            elif level == 0:
                # should only happen for differences in dictionary keys
                if value != d2[key]:
                    result[key] = value
            else:
                # recurse on the values
                recurse = difference(value, d2.get(key, {}), level - 1)
                if recurse:
                    if key in result:
                        result[key].update(recurse)
                    else:
                        result[key] = recurse
        else:
            result[key] = value
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from `d1` not contained in `d2`.

    `level` sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in `d1` and `d2` but has different values,
    it is included into the difference.
    See :func: `intersection` for more details.

    `d1` and `d2` remain unchanged. However, `d1` or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument `level`.
    """
    result = {}
    if level == -1:
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif v != d2[k]:
                result[k] = v
    else:
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif isinstance(v, dict) and isinstance(d2[k], dict) and level > 0:
                sub_result = difference(v, d2[k], level-1)
                if sub_result:
                    result[k] = sub_result
            elif v != d2[k]:
                result[k] = v

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    difference = copy.deepcopy(d1)
    for k in d2:
        if k in d1:
            if isinstance(d1[k], dict) and isinstance(d2[k], dict) and level > 0:
                difference[k] = difference(d1[k], d2[k], level - 1)
            elif d1[k] == d2[k]:
                del difference[k]
            else:
                difference[k] = d1[k]
        else:
            difference[k] = d1[k]
    return difference

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord in self:
        self[coord] += weight
    else:
        self[coord] = weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < 0 or coord >= len(self.sampling):
        return

    i = coord
    while i >= 0 and self.sampling[i] <= weight:
        self.sampling[i] += weight
        i -= 1

    while i < len(self.sampling) - 1 and self.sampling[i + 1] <= weight:
        self.sampling[i + 1] += weight
        i += 1

    while i >= 0 and self.sampling[i] > 1:
        self.sampling[i] -= 1
        i -= 1

    while i < len(self.sampling) - 1 and self.sampling[i + 1] > 1:
        self.sampling[i + 1] -= 1
        i += 1

    if i < 0:
        self.sampling[0] = weight
    elif i >= len(self.sampling):
        self.sampling[-1] = weight
    else:
        self.sampling[i] = weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []
    for key, value in labels.items():
        if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", key):
            errors.append({
                "key": key,
                "message": f"Label key '{key}' does not match the regex '^[a-zA-Z_][a-zA-Z0-9_]*$'"
            })
        if not isinstance(value, str):
            errors.append({
                "key": value,
                "message": "expected string or bytes-like object"
            })
    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective regular expression. The error contains as message the list of all errors which occurred in the labels. Each element of the list is a dictionary with one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    errors = []
    for label, value in labels.items():
        if not isinstance(label, str):
            errors.append({str(label): 'expected string or bytes-like object'})
        if not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})

        if isinstance(value, list):
            for i, item in enumerate(value):
                if not isinstance(item, str):
                    errors.append({str(value): 'expected string or bytes-like object'})

        if label.startswith('$$'):
            errors.append({label: "Label key '$$' does not match the regex [...]'}"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    errors = []
    for key, value in labels.items():
        if not LABEL_KEY_RE.match(key):
            errors.append({"'{}'".format(key): "Label key '{}' does not match the regex '{}'".format(key, LABEL_KEY_RE.pattern)})
        if not LABEL_VALUE_RE.match(value):
            errors.append({"'{}'".format(value): "Label value '{}' does not match the regex '{}'".format(value, LABEL_VALUE_RE.pattern)})
    if errors:
        raise ValidationError("Some of the labels do not match their respective regular expressions. See error messages for details.", errors)

