def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """ Generate part of a default observer schema from a partial Kubernetes resource. """

    # Create a new dictionary with the same keys as the input manifest_dict
    observer_schema = {key: None for key in manifest_dict.keys()}

    # Fill the new dictionary with None values
    for key, value in observer_schema.items():
        if isinstance(value, list):
            # Recursively call the function for list elements
            observer_schema[key] = [generate_default_observer_schema_dict(element) for element in value]
        elif isinstance(value, dict):
            # Recursively call the function for dict elements
            observer_schema[key] = generate_default_observer_schema_dict(value)
        else:
            # Replace all non-list and non-dict values by None
            observer_schema[key] = None

    # If the input dictionary is the root of an observer schema, copy identifying fields from the manifest file
    if first_level:
        observer_schema["apiVersion"] = manifest_dict["apiVersion"]
        observer_schema["kind"] = manifest_dict["kind"]
        observer_schema["schemaVersion"] = manifest_dict["schemaVersion"]
        observer_schema["meta"]["id"] = manifest_dict["metadata"]["name"]

    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(observer_schema)):
        if i >= len(response):
            # We have reached the end of the response, which means some observed fields are missing, so we can initialize them in last_applied_manifest
            last_applied_manifest.append(observer_schema[i][1].__class__.default())
        elif observer_schema[i][1].type == 'list':
            # We are dealing with a list field, so we need to recursively update the children
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observer_schema[i][1]._child_schema, response[i])
        elif observer_schema[i][1].type == 'dict':
            # We are dealing with a dict field, so we need to recursively update the children
            last_applied_manifest.update(update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], observer_schema[i][1]._child_schema, response[i]))
        else:
            # We are dealing with a primitive field, so we can set its value from the response
            last_applied_manifest[i] = response[i]

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for obj in response:
        if len(observer_schema) == 1:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema[0], obj)
        else:
            for field in observer_schema:
                if field.name in obj:
                    if field.type == 'list':
                        if field.items is None:
                            update_last_applied_manifest_list_from_resp(last_applied_manifest.get(field.name), field.items, field.schema)
                        else:
                            update_last_applied_manifest_list_from_resp(last_applied_manifest.get(field.name), field.items, obj.get(field.name))
                    else:
                        update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(field.name), field.schema, obj.get(field.name))
                else:
                    new_obj = {}
                    if field.type == 'list':
                        if field.items is None:
                            update_last_applied_manifest_list_from_resp(new_obj, field.items, field.schema)
                        else:
                            update_last_applied_manifest_list_from_resp(new_obj, field.items, obj)
                    else:
                        update_last_applied_manifest_dict_from_resp(new_obj, field.schema, obj)
                    last_applied_manifest[field.name] = new_obj

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """
    Recursively updates a partial "last_applied_manifest" from a partial Kubernetes response
    """
    for observer, value in zip(observer_schema, response):
        if isinstance(observer, list):
            if observer[0] == "array":
                if observer[1] == "last_applied_manifest":
                    if len(last_applied_manifest) < len(response):
                        last_applied_manifest.append(observer[1])
                update_last_applied_manifest_list_from_resp(last_applied_manifest, observer, value)
        else:
            if observer == "last_applied_manifest":
                if len(last_applied_manifest) < len(response):
                    last_applied_manifest.append(observer)
            else:
                last_applied_manifest[observer] = value
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for observed_field in observer_schema:
        if observed_field not in response:
            raise KeyError(f"Observed field {observed_field} is not present in the Kubernetes response")
        if observed_field not in last_applied_manifest:
            last_applied_manifest[observed_field] = response[observed_field]
        elif type(observer_schema[observed_field]) == dict and type(last_applied_manifest[observed_field]) == dict:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[observed_field], observer_schema[observed_field], response[observed_field])
        elif type(observer_schema[observed_field]) == list and type(last_applied_manifest[observed_field]) == list:
            for i in range(len(observer_schema[observed_field])):
                if type(observer_schema[observed_field][i]) == dict:
                    update_last_applied_manifest_dict_from_resp(last_applied_manifest[observed_field][i], observer_schema[observed_field][i], response[observed_field][i])
                else:
                    if observed_field not in last_applied_manifest[observed_field]:
                        last_applied_manifest[observed_field].append(response[observed_field][i])

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app.spec.manifest:
        for resource in app.spec.manifest:
            if not resource.observer_schema:
                resource.observer_schema = {"$schema": "https://json-schema.org/draft/2019-09/schema"}
    else:
        raise ValueError("The given application does not have any manifest")

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`) contains the set of in-style parameters. It maps each parameter (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style` is a named parameter style, then *params* must be a :class:`~collections.abc.Mapping`. If :attr:`.SQLParams.in_style` is an ordinal parameter style, then *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).

    - The set of converted out-style parameters (:class:`dict` or :class:`list`).
    """

    if isinstance(params, dict):
        out_params = {}
        for name, value in params.items():
            out_params[name] = value
    else:
        out_params = []
        for value in params:
            out_params.append(value)

    return (
        sql.replace(":", "?", 1) if self.in_style.name == "in_style" else sql.replace("?", ":", 1),
        out_params
    )

def formatmany(self, sql, many_params):
    """Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    sql: Union[str, bytes]
    many_params: Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]

    Returns: Tuple[Union[str, bytes], List[Dict[Any, Any]], Any]
    """
    if self.SQLParams.in_style == 'named':
        if not isinstance(many_params[0], dict):
            raise ValueError('Expected `many_params` to be a list of dicts')
    else:
        if not isinstance(many_params[0], tuple):
            raise ValueError('Expected `many_params` to be a list of tuples')

    params_count = len(many_params)
    param_names = self.SQLParams.names
    formatted_params = {param_name: None for param_name in param_names}
    out_params = []

    for i, params in enumerate(many_params):
        formatted_row = self.format(sql, params)
        out_row = []

        if self.SQLParams.in_style == 'named':
            row_params = {k: v for k, v in params.items() if k in param_names}
        else:
            row_params = dict(zip(param_names, params))

        for param_name, param_value in row_params.items():
            if param_value is not None:
                out_row.append(param_value)
                formatted_params[param_name] = param_value
            else:
                out_row.append('')

        out_params.append(out_row)

    return formatted_params, out_params, params_count

