        prefix (str): Prefix to prepend to the status string. Defaults to ''.

    Returns:
        str: String representing the validator status.
    """

    status_flags = []
    if self._has_missing_required:
        status_flags.append('missing required')
    if self._has_invalid_required:
        status_flags.append('invalid required')
    if self._has_excess_required:
        status_flags.append('excess required')
    if self._has_missing_optional:
        status_flags.append('missing optional')
    if self._has_invalid_optional:
        status_flags.append('invalid optional')
    if self._has_excess_optional:
        status_flags.append('excess optional')

    status_str = ', '.join(status_flags)
    if prefix:
        prefix = prefix + ' '
    return f'{prefix}{status_str}'

