    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Check if the inventory is a valid type and is a list
    if not isinstance(inventory, list) or len(inventory) < 1:
        raise ValueError("Inventory must be a non-empty list")

    # Check if the spec_version is valid or can be extracted from the inventory
    if extract_spec_version and len(inventory) > 0:
        spec_version = self.extract_spec_version(inventory[0])
        if spec_version is None:
            raise TypeError("Unable to extract a valid specification version from the inventory")
    else:
        spec_version = self.spec_version

    # Run the validation process for the specified specification version
    if spec_version is None:
        raise ValueError("No specification version specified")
    elif spec_version == "0.2":
        self.validate_v0_2(inventory)
    elif spec_version == "0.3":
        self.validate_v0_3(inventory)
    else:
        raise ValueError(f"Unsupported specification version '{spec_version}'")

