        type_value = inventory.get("type")
        if type_value and type_value.startswith("urn:oasis:names:tc:xliff:document:"):
            self.spec_version = type_value.split(":")[2]

    # Validate the inventory against the specified specification version
    if not self.validate_spec_version(self.spec_version):
        raise ValueError(f"The specified version ({self.spec_version}) is not a valid version.")

    # Validate the inventory against the type value
    if extract_spec_version:
        type_value = inventory.get("type")
        if type_value and type_value.startswith("urn:oasis:names:tc:xliff:document:"):
            type_spec_version = type_value.split(":")[2]
            if self.spec_version != type_spec_version:
                raise ValueError(f"The type value ({type_value}) does not match the specified version ({self.spec_version}).")

    # Validate the inventory against the required attributes and elements
    try:
        self.load(inventory)
    except ValidationError as e:
