        raise Exception(err)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    digests_needed = [
        d for path, _, d in manifest_files
        if path in self.manifest_paths_needing_digests
    ]

    digests_present = {
        d.digest_algorithm: len(d.digests)
        for mf in manifest_files
        for d in mf.digests
        if d.digest_algorithm in self.supported_digest_algorithms
    }

    digests_used = Counter(
        d.digest_algorithm for mf in manifest_files
        for d in mf.digests
    )

    digests_missing = digests_needed - digests_present.keys()
    digests_unused = digests_used - digests_present.values()

    if digests_missing:
        raise ValueError(
            f"The following digest algorithms required by manifest files "
            f"{self.manifest_paths_needing_digests} are not present in the "
            f"manifest: {', '.join(digests_missing)}."
        )

    if digests_unused:
        raise ValueError(
            f"The following digest algorithms are not needed by any of the "
            f"manifest files: {', '.join(digests_unused)}."
        )

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used.

    Arguments:
        manifest_files (list): List of manifest files to check
        digests_used (list): List of digests used in the manifest

    Returns:
        bool: True if all digests are present and used, False otherwise
    """

    for manifest_file in manifest_files:
        if not manifest_file.digests:
            continue

        for digest in manifest_file.digests:
            if manifest_file not in digests_used:
                return False

    return True

