def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that prior is not None
    if prior is None:
        raise ValueError("Prior version must not be None")

    # Check that prior and self are of the same type
    if type(prior) is not type(self):
        raise ValueError(f"Prior version must be of type {type(self)}")

    # Check that prior and self have the same version
    if prior.get_version() != self.get_version():
        raise ValueError(f"Prior version ({prior.get_version()}) does not match self version ({self.get_version()})")

    # Check that prior and self have the same inventory keys
    if prior.get_inventory_keys() != self.get_inventory_keys():
        raise ValueError(f"Prior version inventory keys ({prior.get_inventory_keys()}) do not match self inventory keys ({self.get_inventory_keys()})")

    # Check that prior and self have the same inventory values
    for key in prior.get_inventory_keys():
        if prior.get_inventory_value(key) != self.get_inventory_value(key):
            raise ValueError(f"Prior version inventory value for key {key} ({prior.get_inventory_value(key)}) does not match self inventory value ({self.get_inventory_value(key)})")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    if not isinstance(prior, InventoryValidator):
        raise TypeError("Prior is not an InventoryValidator object.")

    if (
        self.version != prior.version - 1
        or self.uuid != prior.uuid
        or self.application != prior.application
        or self.identifier != prior.identifier
    ):
        raise InventoryVersionMismatchError(
            f"Prior version of inventory with UUID {self.uuid} does not match. Prior version: {prior.version}, current version: {self.version}, prior application: {prior.application}, current application: {self.application}, prior identifier: {prior.identifier}, current identifier: {self.identifier}"
        )

    # Check that the objects in the prior inventory are all subclasses of the corresponding objects in the current inventory
    for obj_type in prior.objects:
        if obj_type not in self.objects or not issubclass(
            self.objects[obj_type], prior.objects[obj_type]
        ):
            raise InventoryVersionMismatchError(
                f"Object type {obj_type} in prior inventory is not a subclass of the corresponding object type in the current inventory."
            )

    # Check that the attributes of the objects in the prior inventory are all present in the corresponding objects in the current inventory and have consistent values
    for obj_type in prior.objects:
        for obj_id in prior.objects[obj_type]:
            current_obj = self.objects[obj_type].get(obj_id)
            prior_obj = prior.objects[obj_type].get(obj_id)

            if current_obj is None or prior_obj is None:
                raise InventoryVersionMismatchError(
                    f"Object with ID {obj_id} in prior inventory is not in the corresponding object in the current inventory."
                )

            for attr_name in prior_obj.attributes:
                if attr_name not in current_obj.attributes:
                    raise InventoryVersionMismatchError(
                        f"Attribute {attr_name} in prior inventory is not in the corresponding object in the current inventory."
                    )

                if current_obj.attributes[attr_name] != prior_obj.attributes[attr_name]:
                    raise InventoryVersionMismatchError(
                        f"Values of attribute {attr_name} in prior inventory and corresponding object in current inventory do not match."
                    )

    # Check that the relations of the objects in the prior inventory are all present in the corresponding objects in the current inventory and have consistent values
    for obj_type in prior.objects:
        for obj_id in prior.objects[obj_type]:
            current_obj = self.objects[obj_type].get(obj_id)
            prior_obj = prior.objects[obj_type].get(obj_id)

            if current_obj is None or prior_obj is None:
                raise InventoryVersionMismatchError(
                    f"Object with ID {obj_id} in prior inventory is not in the corresponding object in the current inventory."
                )

            for rel_type in prior_obj.relations:
                if rel_type not in current_obj.relations:
                    raise InventoryVersionMismatchError(
                        f"Relation {rel_type} in prior inventory is not in the corresponding object in the current inventory."
                    )

                current_relations = current_obj.relations[rel_type]
                prior_relations = prior_obj.relations[rel_type]

                if len(current_relations) != len(prior_relations):
                    raise InventoryVersionMismatchError(
                        f"Number of relations of type {rel_type} in prior inventory and corresponding object in current inventory do not match."
                    )

                for rel_name in prior_relations:
                    if rel_name not in current_relations:
                        raise InventoryVersionMismatchError(
                            f"Relation {rel_name} in prior inventory is not in the corresponding object in the current inventory."
                        )

                    if current_relations[rel_name] != prior_relations[rel_name]:
                        raise InventoryVersionMismatchError(
                            f"Values of relation {rel_name} in prior inventory and corresponding object in current inventory do not match."
                        )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
