def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, list):
        raise ValueError("Fixity block is not a list")

    for f in fixity:
        if not isinstance(f, dict):
            raise ValueError("Fixity entry is not a dict")
        if "value" not in f:
            raise ValueError("Fixity entry missing 'value' key")
        if "checksumAlgorithm" not in f:
            raise ValueError("Fixity entry missing 'checksumAlgorithm' key")
        if "URI" not in f:
            raise ValueError("Fixity entry missing 'URI' key")

    for f in fixity:
        value = f["value"]
        checksumAlgorithm = f["checksumAlgorithm"]
        URI = f["URI"]

        if value == "":
            raise ValueError("Fixity entry has empty 'value'")
        if checksumAlgorithm == "":
            raise ValueError("Fixity entry has empty 'checksumAlgorithm'")
        if URI == "":
            raise ValueError("Fixity entry has empty 'URI'")

        if URI not in manifest_files:
            raise ValueError("Fixity URI " + URI + " not found in manifest")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check the structure of the fixity block
    if not isinstance(fixity, dict) or "checksums" not in fixity:
        raise ValueError("Expected a dictionary with a 'checksums' key in the fixity block")

    checksums = fixity["checksums"]
    if not isinstance(checksums, list):
        raise ValueError("Expected the 'checksums' value in the fixity block to be a list")

    # Check that only files listed in the manifest are referenced
    for checksum in checksums:
        if "path" not in checksum or "value" not in checksum:
            raise ValueError("Expected each item in the 'checksums' list to be a dictionary with 'path' and 'value' keys")
        path = checksum["path"]
        if path not in manifest_files:
            raise ValueError(f"File {path} is referenced in the fixity block but not included in the manifest")

def file_list(path):
    """
    Return the files in `path`
    """
    files=[]
    for file in os.listdir(path):
        file_path = os.path.join(path, file)
        if os.path.isfile(file_path):
            files.append(file_path)
        elif os.path.isdir(file_path):
            files += file_list(file_path)
    return files

def _explore_folder(folder):
    packages_dict = {}
    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_name = os.path.splitext(file)[0]
                package_name = file_name.split('-')[0]
                if package_name not in packages_dict:
                    packages_dict[package_name] = []
                package_data = {}
                package_data['path'] = os.path.join(root, file)
                package_data['files'] = []
                packages_dict[package_name].append(package_data)
    return packages_dict

