def _extract_number_and_supplment_from_issue_element(issue):
    issue_content = issue.text_content().strip()
    number_suffix_regex = re.compile('^(.*?)((Suppl|Spe|s2)\.)?$')

    match = number_suffix_regex.match(issue_content)
    if match:
        number = match.group(1).strip()
        supplment = match.group(2)
        if supplment:
            supplment = supplment.strip('.-')
        return number, supplment
    else:
        return None, None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    prefix = '    ' * indent
    output = []
    if debug:
        output.append(prefix + '#' + str(id(self)) + ' ' + self.__class__.__name__ + ':')
    output.append(prefix + '{')

    # Print the attributes of self
    for attr in dir(self):
        if not attr.startswith('_'):
            value = getattr(self, attr)
            if isinstance(value, (list, tuple)):
                output.append(prefix + '    ' + repr(value))
            elif isinstance(value, dict):
                output.append(prefix + '    {}'.format(repr(dict(value))))
            else:
                output.append(prefix + '    ' + repr(value))

    output.append(prefix + '}')
    return '\n'.join(output)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    lines = []
    spaces = indent * " "
    line = f"{spaces}{self.__class__.__name__}(\n"
    lines.append(line)
    for attr, value in self.__dict__.items():
        if attr in ("string", "ptr", "shape"):
            continue
        if isinstance(value, (list, tuple, dict)):
            if debug:
                line = f"{spaces}    {attr}={repr(value)}\n"
            else:
                line = f"{spaces}    {attr}={len(value)}\n"
            lines.append(line)
        else:
            if debug:
                line = f"{spaces}    {attr}={repr(value)}\n"
            else:
                line = f"{spaces}    {attr}={value}\n"
            lines.append(line)
    if debug:
        line = f"{spaces}    string={repr(self.string)}\n"
        lines.append(line)
        line = f"{spaces}    ptr={self.ptr and (repr(self.ptr.name) + ':' + repr(self.ptr.id)) or 'None'}\n"
        if self.ptr is not None:
            lines.append(line)
    line = f"{spaces})"
    lines.append(line)
    return "".join(lines)

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """

        result = []

        for i in range(len(args)):
            if i % 2 == 0:
                left = args[i]

                if isinstance(left, Clause):
                    if left.op == '|':
                        right = args[i + 1]
                        if isinstance(right, Clause):
                            if right.op == '&':
                                # Absorption: A & (A | B) = A
                                if left.args[0] == right.args[0]:
                                    result.extend(left.args[0])
                                # Absorption: A | (A & B) = A
                                elif left.args[0] == right.args[1]:
                                    result.extend(left.args[0])
                            elif right.op == '|':
                                # Negative absorption: A & (~A | B) = A & B
                                if left.args[0] != right.args[0]:
                                    result.extend(left.args[0])
                                    result.extend(right.args[1])
                                # Negative absorption: A | (~A & B) = A | B
                                elif left.args[0] != right.args[1]:
                                    result.extend(left.args[0])
                                    result.extend(right.args[0])

        return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []
    for arg in args:
        if isinstance(arg, Expression):
            # Check if we're dealing with a binary operator
            if arg.operator.type in ['&', '|']:
                # Make a copy of the operator
                new_op = copy.deepcopy(arg.operator)

                # Check if we're absorbing
                if new_op.type == '&':
                    if new_op.left.value == arg.right.value:
                        new_op.left = arg.left
                    elif new_op.right.value == arg.right.value:
                        new_op.right = arg.left
                # Check if we're negative absorbing
                elif new_op.type == '|':
                    if new_op.left.value == arg.right.value:
                        new_op.left = arg.right
                    elif new_op.right.value == arg.right.value:
                        new_op.right = arg.right

                # Append the new operator
                new_args.append(Expression(new_op, arg.left, arg.right))
            # Otherwise, just append the expression as-is
            else:
                new_args.append(arg)

    return new_args

def absorb(self, args):
    new_list = []
    for arg in args:
        if arg.op == "&":
            if arg.a.op == "|" and arg.a.a == self:
                new_list.append(arg.a.b)
            elif arg.a == self and arg.b.op == "|":
                new_list.append(arg.b.a)
            else:
                new_list.append(arg)
        elif arg.op == "|":
            if arg.a.op == "&" and arg.a.a == self:
                new_list.append(arg.a.b)
            elif arg.a == self and arg.b.op == "&":
                new_list.append(arg.b.a)
            else:
                new_list.append(arg)
        else:
            new_list.append(arg)
    return new_list

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []
    for arg in args:
        if isinstance(arg, Negation):
            if arg.operator.annotation == "&":
                if isinstance(arg.operand, Negation) and arg.operand.operator.annotation == "&":
                    new_args.append(arg.operand.operand)
                elif isinstance(arg.operand, BinaryOperator) and arg.operand.operator.annotation == "|":
                    new_args.append(arg.operand.left)
            elif arg.operator.annotation == "|":
                if isinstance(arg.operand, Negation) and arg.operand.operator.annotation == "&":
                    new_args.append(arg.operand.operand)
                elif isinstance(arg.operand, BinaryOperator) and arg.operand.operator.annotation == "|":
                    new_args.append(arg.operand.right)
        else:
            new_args.append(arg)
    return new_args

