def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """

    new_attrs = {}

    for attr, value in self.__dict__.items():
        if isinstance(value, float):
            new_attrs[attr] = round(value)
        elif isinstance(value, relativedelta):
            new_attrs[attr] = value.normalized()

    return relativedelta(**new_attrs)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        # If we are in Python 2, tzname() returns a string and no conversion is necessary
        return namefunc
    else:
        # In Python 3, tzname() returns a unicode string, which needs to be converted to bytestring
        return namefunc().encode('ascii')

def tzname_in_python2(namefunc):
    def convert(name):
        if isinstance(name, bytes):
            return name.decode('ascii')
        return name
    return lambda x, y, z: convert(namefunc(x, y, z))

