def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    from typing import List

    if isinstance(commands, str):
        commands = [commands]
    elif isinstance(commands, List):
        commands = list(commands)
    else:
        raise ValueError("commands must be a string or a list of strings")

    if env is not None:
        if isinstance(env, str):
            os.environ = env
        elif isinstance(env, List):
            os.environ = os.environ.copy()
            for k, v in env.items():
                os.environ[k] = v
        else:
            raise ValueError("env must be a string or a dictionary")

    if isinstance(args, str):
        args = [args]
    elif isinstance(args, List):
        args = list(args)
    else:
        raise ValueError("args must be a string or a list of strings")

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    proc = subprocess.Popen(
        commands + args,
        cwd=cwd,
        env=os.environ,
        stderr=stderr,
        universal_newlines=True,
    )
    output = proc.communicate()
    retcode = proc.returncode

    if retcode != 0:
        raise subprocess.CalledProcessError(retcode, commands, output=output)

    if verbose:
        print(output)
    return output

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands == None:
        raise ValueError("commands are required")
    elif not is_iterable(commands):
        raise ValueError("commands must be an iterable object")
    if not isdict(args):
        raise ValueError("args must be a dictionary")

    if cwd != None:
        if not isinstance(cwd, str):
            raise ValueError("cwd must be a string")

    # Set the default value for env
    if env == None:
        env = dict()
    elif not isdict(env):
        raise ValueError("env must be a dictionary")

    # Set the default value for verbose
    if verbose == None:
        verbose = False
    elif not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")

    # Set the default value for hide_stderr
    if hide_stderr == None:
        hide_stderr = False
    elif not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")

    proc = subprocess.Popen(commands, shell=True) # Core call function in the subprocess library.

    if not isinstance(proc, subprocess.Popen):
        raise Exception("Failed to execute command {commands}.")

    # If account_signups variable is false, skip this part
    stdout, stderr = proc.communicate() # Gets the output of the process.

    if verbose:
        print("Command output:")
        print(stdout)

    if hide_stderr and stderr:
        raise Exception(stderr)

    # Check the status code of the process
    if proc.returncode != 0:
        raise Exception(f"Command failed with return code {proc.returncode}")

    return proc.returncode == 0

