def validate_version_inventories(self, version_dirs):
    """Validate that each version has an inventory up to that point.

    Also record any content digests that differ from those in the root inventory.

    version_dirs is an array of version directory names and is assumed to be in version sequence (1, 2, 3...).
    """

    self.inventory_contents = []
    self.digests_from_previous_versions = {}

    for version_dir in version_dirs:
        inventory_filename = os.path.join(self.root_dir, version_dir, "inventory.csv")
        with open(inventory_filename, "r") as inventory_file:
            inventory_reader = csv.DictReader(inventory_file)
            inventory_contents = [row for row in inventory_reader]
        self.inventory_contents.append(inventory_contents)

        if version_dir != version_dirs[-1]:
            for row in inventory_contents:
                digest = row["Content Digest"]
                previous_version = self.digests_from_previous_versions.get(digest)
                if previous_version:
                    raise ValueError(f"Content digest '{digest}' already used in version {previous_version}")
                self.digests_from_previous_versions[digest] = version_dir

        content_dir = os.path.join(self.root_dir, version_dir, "content")
        for file in os.listdir(content_dir):
            file_path = os.path.join(content_dir, file)
            if os.path.isfile(file_path):
                digest = hashlib.sha256(open(file_path, "rb").read()).hexdigest()
                if digest in self.digests_from_previous_versions:
                    raise ValueError(f"Content file '{file_path}' has the same content digest as version {self.digests_from_previous_versions[digest]}.")

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.inventory
    root_digests = {}
    for entry in root_inventory.items():
        root_digests[entry.path] = entry.digest

    for i in range(len(version_dirs)):
        version_dir = version_dirs[i]
        version_inventory = self.get_inventory(version_dir)
        for entry in version_inventory.items():
            if entry.path in root_digests:
                if entry.digest != root_digests[entry.path]:
                    raise ValueError("Inventory mismatch for file '" + entry.path + "' in version directory '" + version_dir + "'")
            else:
                root_digests[entry.path] = entry.digest

