def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isdir(path):
        for f in os.listdir(path):
            if f.startswith("0=*"):
                try:
                    with open(os.path.join(path, f), "r") as f:
                        lines = f.readlines()
                        if lines[0].startswith("0="):
                            if lines[0].startswith("0=directory"):
                                return "object"
                            elif lines[0].startswith("0=storage"):
                                return "root"
                except:
                    return "ERROR: could not read '0=*' file"

        return "file"
    else:
        return "ERROR: path does not exist"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isdir(path):
        for child in os.listdir(path):
            child_path = os.path.join(path, child)
            if os.path.isdir(child_path):
                if child == 'versions':
                    return 'object'
                if child.startswith('0='):
                    return 'object'
                return 'root'
        return 'root'
    if os.path.isfile(path):
        if path.endswith('.TXT'):
            return 'file'
        if path.endswith('.inv'):
            return 'file'
    return 'unknown'

