def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser instance,
    give each requested action's subparser a shot at parsing all arguments. This allows common arguments like
    "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of arguments, a
    list of remaining arguments not claimed by any subparser).
    """

    # Create a new argparse.ArgumentParser instance for each subparser
    subparser_names = list(subparsers.keys())
    subparser_parsers = {name: subparsers[name].copy() for name in subparser_names}

    # Add all common arguments to each subparser parser
    for name in subparser_names:
        for arg in subparsers['*']._actions:
            subparser_parsers[name].add_argument(
                *arg.option_strings,
                dest=arg.dest,
                help=arg.help,
                metavar=arg.metavar)

    # Parse the input arguments for each subparser
    subparser_namespace = {
        name: parser.parse_args(unparsed_arguments)
        for name, parser in subparser_parsers.items()
    }

    # Get the remaining arguments not claimed by any subparser
    remaining_arguments = [
        arg for arg in unparsed_arguments
        if arg not in (
            arg
            for subparser in subparser_namespace.values()
            for arg in vars(subparser).values()
        )
    ]

    return (subparser_namespace, remaining_arguments)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    for argument in unparsed_arguments:
        for subparser_name, parser in subparsers.items():
            try:
                namespace = parser.parse_args([argument])
                parsed_arguments[subparser_name] = namespace
                break
            except SystemExit:
                remaining_arguments.append(argument)

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser instance, give each requested action's subparser a shot at parsing all arguments. This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    parser_args = {}
    remaining_args = []
    for arg in unparsed_arguments:
        for key, parser in subparsers.items():
            try:
                parser_args[key] = parser.parse_args(arg.split())
            except SystemExit:
                remaining_args.append(arg)
    return parser_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parser_arguments = {}
    remaining_arguments = []

    for arg in unparsed_arguments:
        for parser in subparsers.values():
            try:
                arguments = parser.parse_args([arg])
                if parser.prog not in parser_arguments:
                    parser_arguments[parser.prog] = arguments
                else:
                    parser_arguments[parser.prog].args.extend(arguments.args)
            except SystemExit:
                remaining_arguments.append(arg)

    return parser_arguments, remaining_arguments

