    result = []
    for (key, value) in nodes:
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            # If this value is a mapping, we need to recursively call `deep_merge_nodes` on its
            # values and then merge the results with the previous values.
            new_value = deep_merge_nodes(value.value)
            if key in result:
                # If we already have a value for this key, we need to merge the current value with
                # the previous value.
                (_, prev_value) = result[key]
                result[key] = (key, merge_nodes(prev_value, new_value))
            else:
                # Otherwise, we just need to add the current value to the result.
                result.append((key, new_value))
        else:
            # If this value is not a mapping, we just need to add it to the result.
            result.append((key, value))
    return result

