    def _get_subcommand_parser(subparsers):
        return [
            subparser for subparser in subparsers.values()
            if isinstance(subparser, argparse.ArgumentParser)
        ]

    def _get_arguments_names(parser):
        return [
            argument.dest for argument in parser._actions
            if argument.option_strings and argument.dest != "help"
        ]

    def _get_subcommand_arguments_names(subparser):
        return [
            argument.dest for argument in subparser._actions
            if argument.option_strings and argument.dest != "help"
        ]

    def _get_subcommand_subparsers(subparser):
        return {
            subparser.choices[args[0]] for args in subparser._option_string_actions
            if args[0] not in ("help",) and args[0] not in subparser._subparsers
        }

    def _get_subcommand_docstring(subparser):
        return subparser.description or subparser.epilog

    def _get_subcommand_bash_completion(subparser):
        return subparser.epilog

    def _get_parser_options(parser, depth=0):
        for option in parser._option_string_actions:
            yield from [
                " %s-%s" % (" " * depth, option[0])
                for option in parser._option_string_actions
                if option[0] not in ("help",)
            ]
        for subparser in _get_subcommand_subparsers(parser):
            yield from [
                " %s-%s" % (" " * depth, subparser.prog or subparser.prog.split(" ")[-1])
                for subparser in _get_subcommand_subparsers(parser)
            ]

    parser = argparse.ArgumentParser(prog="borgmatic", description="Microscopic backup tool")
    yield from (_get_parser_options(parser))
    subparser = parser.add_subparsers()
    subparsers = {
        subparser.choices[args[0]]: _get_subcommand_parser(subparser)
        for args in subparser._option_string_actions
        if args[0] not in ("help",)
    }

    for subparser in subparsers:
        yield from (
            _get_arguments_names(subparser),
            _get_subcommand_arguments_names(subparser),
        )
        for sub_subparser in _get_subcommand_subparsers(subparser):
            yield from (
                _get_arguments_names(sub_subparser),
                _get_subcommand_arguments_names(sub_subparser),
            )

    def _get_docstring_option_string_function(decorator):
        def function(parser, prog_name=None):
            yield from (
                "'%s'" % option.upper()
                for option in parser._option_string_actions
                if option[0] not in ("help",) and not option[0].isalpha()
            )
        return decorator(function)

    @_get_docstring_option_string_function
    def _get_bash_completion_option_string_function(parser, prog_name=None):
        for subparser in _get_subcommand_subparsers(parser):
            if _get_bash_completion_option_string_function(subparser)():
                yield from (
                    "'%s'" % option.upper()
                    for option in subparser._option_string_actions
                    if option[0] not in ("help",) and not option[0].isalpha()
                )

    yield from _get_subcommand_bash_completion(subparsers.items()[0][1][0])

