def parse_subparser_arguments(unparsed_arguments, subparsers):
    remaining_arguments = []
    parsed_arguments = {}

    for argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            if not subparser.has_args or argument in subparser.has_args:
                if argument in subparser:
                    parsed_arguments[subparser_name] = subparser.parse_args([argument])
                    break
                if argument == "-h" or argument == "--help":
                    raise TooManyArgumentsError("Too many arguments inputted!")
                if argument == "-":
                    with open(sys.stdin.fileno()) as f:
                        lines = f.readlines()
                    for line in lines:
                        remaining_arguments.append(line.rstrip())
            else:
                remaining_arguments.append(argument)

    for subparser_name, subparser in subparsers.items():
        if subparser_name not in parsed_arguments:
            if subparser.default is None:
                parsed_arguments[subparser_name] = subparser.parse_args(remaining_arguments)
            else:
                parsed_arguments[subparser_name] = subparser.parse_args(remaining_arguments + [subparser.default])

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dictionary matching subparser names to Argparse
    parser objects, parse all arguments and recognize any common options. This supports shared options, like --repository, that are used across multiple subparsers.

    Return this as a tuple of (a dictionary mapping subparser names to recognized options, a list of unprocessed command-line options).
    '''
    parsed_options = {}
    processed_arguments = []

    for arg in unparsed_arguments:
        if arg.startswith("-"):
            # handle shared arguments
            if arg in subparsers[next(iter(subparsers))]._option_string_actions:
                option, value = arg.split("=", 1)
                if option in subparsers:
                    for name, parser in subparsers.items():
                        if option in parser._option_string_actions:
                            processed_arguments.append(f"--{name}")
                            processed_arguments.append(value)
                            parsed_options[name] = parser.parse_args(["--{}={}".format(option, value)])
            else:
                # handle subparser-specific arguments
                for name, parser in subparsers.items():
                    if arg in parser._option_string_actions:
                        processed_arguments.append(f"--{name}")
                        if arg.startswith("-"):
                            processed_arguments.append(arg.split("=", 1)[1])
                        else:
                            processed_arguments.append(arg)
                        parsed_options[name] = parser.parse_args(["--{}{}".format(option, value)])
                        break
        else:
            # handle non-option arguments
            for name, parser in subparsers.items():
                if arg in subparsers[name]._option_string_actions:
                    processed_arguments.append(arg)
                    parsed_options[name] = parser.parse_args(["--{}={}".format(option, value)])
                    break
                else:
                    processed_arguments.append(arg)

    return parsed_options, processed_arguments

class Parser:
    def __init__(self, name):
        self.name = name
        self.subparsers = {}

    def add_subparser(self, subparser):
        self.subparsers[subparser.name] = subparser

    def build(self, subparsers):
        parser = subparsers.add_parser(self.name, help=self.__doc__)

        for subparser in self.subparsers.values():
            subparser.build(parser.add_subparsers())

        return parser

    def parse(self, args):
        parser = self.build(argparse.ArgumentParser())
        return parser.parse_args(args)

