def int_to_string(i: int, alphabet: List[str]) -> str:
    """
    Convert an integer to a string, using the given alphabet.

    The output is assumed to have the most significant digit first.
    """

    result = []
    while i != 0:
        result.append(alphabet[i % len(alphabet)])
        i //= len(alphabet)

    return ''.join(reversed(result))

