def prepare_repository_from_archive(archive_path, filename, tmp_path="/tmp"):
    # Unzip the archive
    unzip_output = subprocess.run(
        ["unzip", "-d", tmp_path, archive_path],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if unzip_output.returncode != 0:
        raise subprocess.CalledProcessError(
            unzip_output.returncode,
            unzip_output.args,
            unzip_output.stdout,
            unzip_output.stderr,
        )
    # Return the path to the extracted files
    return os.path.join(tmp_path, filename or os.path.basename(archive_path))

