        process = subprocess.Popen(['git', 'ls-files', '-o'], stdout=subprocess.PIPE)
        out, _ = process.communicate()
        out = out.decode('utf-8')
    except:
        print("Error: unable to retrieve list of ignored files.")
        return None
    ignored_files = sorted([line.rstrip() for line in out.splitlines() if line.startswith("!!")])
    return ", ".join(ignored_files)

