    ignored_file_names.sort()
    ignored_file_names = [f for f in ignored_file_names if f in ignored]
    return ', '.join(ignored_file_names)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    match = re.match(r"^(\d+)(quarterday|businessday|day|week|month|year)$", frequency)
    if match is None:
        raise ValueError(f"Invalid frequency: {frequency}")
    amount = int(match.group(1))
    unit = match.group(2)
    if unit == "quarterday":
        return datetime.timedelta(days=amount * 91)
    elif unit == "businessday":
        return datetime.timedelta(days=amount * 7)
    elif unit == "day":
        return datetime.timedelta(days=amount)
    elif unit == "week":
        return datetime.timedelta(weeks=amount)
    elif unit == "month":
        return datetime.timedelta(days=amount * 30)
    elif unit == "year":
        return datetime.timedelta(days=amount * 365)
    else:
        raise ValueError(f"Invalid frequency unit: {unit}")

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    m = re.match(r"^(?P<num>\d+)\s*(?P<unit>years?|months?|weeks?|days?|hours?|minutes?|seconds?)$", frequency)
    if m:
        num = int(m.group("num"))
        unit = m.group("unit")
        if unit == "years":
            return datetime.timedelta(weeks=num*52)
        elif unit == "months":
            return datetime.timedelta(weeks=num*12)
        elif unit == "weeks":
            return datetime.timedelta(weeks=num)
        elif unit == "days":
            return datetime.timedelta(days=num)
        elif unit == "hours":
            return datetime.timedelta(hours=num)
        elif unit == "minutes":
            return datetime.timedelta(minutes=num)
        elif unit == "seconds":
            return datetime.timedelta(seconds=num)
        else:
            raise ValueError("Invalid frequency: {0}".format(frequency))
    else:
        raise ValueError("Invalid frequency: {0}".format(frequency))

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None

    match = re.match(r"(\d+)\s*([^\s]+)", frequency)
    if match is None:
        raise ValueError(f"Invalid frequency: {frequency}")

    amount = int(match.group(1))
    unit = match.group(2)

    if unit == "week":
        return datetime.timedelta(weeks=amount)
    elif unit == "day":
        return datetime.timedelta(days=amount)
    elif unit == "hour":
        return datetime.timedelta(hours=amount)
    elif unit == "minute":
        return datetime.timedelta(minutes=amount)
    elif unit == "second":
        return datetime.timedelta(seconds=amount)
    else:
        raise ValueError(f"Invalid unit of time: {unit}")

