def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    try:
        url_parts = urllib.parse.urlparse(image_href)
        return (url_parts.path.split("/")[-1], url_parts.netloc, url_parts.scheme == "https")
    except ValueError:
        raise ValueError("Invalid image href: {}".format(image_href))

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    try:
        parsed_uri = urllib.parse.urlparse(image_href)
        netloc = parsed_uri.netloc
        use_ssl = parsed_uri.scheme == "https"
        image_id = parsed_uri.fragment
        if not image_id:
            raise ValueError("Invalid image href: {image_href}")
        return image_id, netloc, use_ssl
    except (ValueError, AttributeError) as e:
        raise ValueError("Invalid image href: {image_href}") from e

