def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is not None and not isinstance(cwd, str):
        cwd = str(cwd)
    if env is not None and not isinstance(env, dict):
        env = dict(env)

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Command must be a string or a list of strings.")

    if not commands:
        raise ValueError("No commands to run.")

    if not args:
        args = []

    if verbose:
        print(" ".join(commands))

    try:
        proc = subprocess.Popen(commands,
                               cwd=cwd,
                               env=env,
                               stdin=subprocess.PIPE,
                               stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE,
                               encoding="utf-8",
                               errors="replace")
    except FileNotFoundError as ex:
        if commands[0] == args[0]:
            raise ValueError(f"{commands[0]} is not executable.") from ex
        else:
            raise ValueError(f"{commands[0]} was not found.") from ex

    (stdoutdata, stderrdata) = proc.communicate(input=args, timeout=None)

    if hide_stderr:
        stderrdata = ""

    if proc.returncode != 0:
        raise subprocess.CalledProcessError(proc.returncode, commands, stderrdata)

    return stdoutdata

