def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    if roots is None:
        roots = set()

    for node, pred, parent in graph.triples((None, prop, None)):
        if parent not in roots:
            roots.add(parent)
            find_roots(graph, prop, roots)

    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for s, o in graph.subject_objects(predicate=prop):
        if s not in roots and o not in roots:
            roots.add(s)
            find_roots(graph, prop, roots)
    return roots

def find_roots(graph, prop, roots=None):
    if not roots:
        roots = set()
    for child in graph.subjects(prop, None):
        if child not in roots:
            roots.add(child)
            find_roots(graph, prop, roots)
    return roots

