def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    parse_errors = []
    for config_filename in config_filenames:
        config = {}
        if overrides and config_filename in overrides:
            config.update(overrides[config_filename])
        try:
            with open(config_filename) as f:
                contents = f.read()
                if resolve_env:
                    contents = _resolve_env(contents)
                config = yaml.load(contents, Loader=yaml.FullLoader)
        except (IOError, yaml.YAMLError) as e:
            logging.getLogger().warning(e)
            logging.getLogger().warning("Unable to load configuration file %s" % config_filename)
            parse_errors.append(logging.LogRecord("WARNING", "Unable to load configuration file %s" % config_filename))
        else:
            configs[config_filename] = config
    return configs, parse_errors

