def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        if protocol_version is None:
            return cls.SUPPORTED_PROTOCOL_VERSIONS
        elif not isinstance(protocol_version, tuple):
            raise TypeError("protocol version must be passed in a tuple")
        elif protocol_version not in cls.SUPPORTED_PROTOCOL_VERSIONS:
            return {}
        else:
            return {protocol_version: cls.SUPPORTED_PROTOCOL_VERSIONS[protocol_version]}

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    # Create a dictionary to hold the supported protocol versions and their handlers
    handlers = {}

    # If a specific protocol version was provided, add it to the dictionary if it's supported
    if protocol_version:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if len(protocol_version) != 2:
            raise ValueError("Invalid protocol version specified")
        if not all(isinstance(i, int) for i in protocol_version):
            raise TypeError("Protocol version must be an integer tuple")

        # If the protocol version is supported, add it to the dictionary
        if protocol_version in cls.SUPPORTED_PROTOCOLS:
            handlers[protocol_version] = cls.SUPPORTED_PROTOCOLS[protocol_version]

    # If no specific protocol version was provided, add all supported versions to the dictionary
    else:
        for version in cls.SUPPORTED_PROTOCOLS:
            handlers[version] = cls.SUPPORTED_PROTOCOLS[version]

    return handlers

def protocol_handlers(protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned."""
    protocol_handlers = {}
    if protocol_version is None:
        for version in supported_protocol_versions:
            protocol_handlers[version] = cls.protocol_handler(version)
