def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph."""

    # Check input arguments
    if not isinstance(hist, histogram):
        raise ValueError("hist must be a histogram")

    if make_value is not None and not callable(make_value):
        raise ValueError("make_value must be a callable or None")

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if not isinstance(field_names, tuple) or len(field_names) != 2:
        raise ValueError("field_names must be a 2-tuple of strings")

    for name in field_names:
        if not isinstance(name, str):
            raise ValueError("field_names must be a 2-tuple of strings")

    if scale is not None and not isinstance(scale, graph.scale):
        raise ValueError("scale must be a graph scale or None")

    # Get histogram data
    num_bins = len(hist.bins)
    points = []
    for i in range(num_bins):
        bin = hist.bins[i]
        if make_value is None:
            value = bin.content
        else:
            context = None if len(bin.contexts) == 0 else bin.contexts[0]
            value = make_value(bin.content, context)

        x = bin.bounds[0]
        if get_coordinate == "left":
            x = bin.bounds[0]
        elif get_coordinate == "right":
            x = bin.bounds[1]
        else:
            x = (bin.bounds[0] + bin.bounds[1]) / 2

        y = value

        points.append((x, y))

    # Create graph
    graph = graph(points=points, field_names=field_names, scale=scale)

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph.

    Args:
        hist (histogram): The histogram to convert.
        make_value (function, optional): A function to set the value of a graph's point. By default, it is bin content.
        get_coordinate (str, optional): The coordinate of the resulting graph point. It can be "left", "right", or "middle".
        field_names (tuple, optional): The field names of the resulting graph. They must be the same length as the dimension of the result.
        scale (Union[bool, graph.scale], optional): The scale of the graph. If it is True, it uses the histogram scale.

    Returns:
        graph: The resulting graph.
    """
    # Set the default make_value function if necessary
    if make_value is None:
        def make_value(bin_):
            return bin_.content

    # Get the coordinate function
    if get_coordinate == "left":
        def get_coordinate(bin_):
            return bin_.left
    elif get_coordinate == "right":
        def get_coordinate(bin_):
            return bin_.right
    elif get_coordinate == "middle":
        def get_coordinate(bin_):
            return (bin_.left + bin_.right) / 2
    else:
        raise ValueError("Invalid value for get_coordinate")

    # Set the field names if they were not provided
    if field_names is None:
        field_names = ("x", "y")

    # Create the graph
    graph = graph.Graph(scale=hist.scale if scale is True else scale)
    for bin_ in hist:
        point = graph.point(coordinates=[get_coordinate(bin_), make_value(bin_)], field_names=field_names)
        graph.append(point)

    return graph

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise ValueError("Invalid input, iface must be a class.")
    if not isinstance(candidate, type):
        raise ValueError("Invalid input, candidate must be a class.")
    if not iface.isabstract() and not iface.issubclass(candidate):
        if tentative:
            logger.warning(
                f"Candidate class {candidate.__name__} does not subclass {iface.__name__},"
                f" but it will work only during runtime."
            )
        else:
            raise ValueError(
                f"Candidate class {candidate.__name__} does not subclass {iface.__name__}"
            )
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the `candidate` might correctly provide `iface`.

    This method is used to ensure that the `candidate` class implements all the necessary methods and properties of the interface `iface`.

    Args:
        iface: The interface class to verify against
        candidate: The class to verify
        tentative (bool, optional): Whether to raise an exception if the verification fails. Defaults to False.

    Returns:
        bool: True if the verification is successful, False otherwise
    """

    # Check that the candidate class implements all the necessary methods
    for method in iface.__dict__.values():
        if not hasattr(candidate, method.__name__):
            if tentative:
                print(f"{candidate.__name__} is missing the {method.__name__} method")
                return False
            else:
                raise AttributeError(f"{candidate.__name__} is missing the {method.__name__} method")

    # Check that the candidate class has all the necessary properties
    for prop, value in iface.__dict__.items():
        if not hasattr(candidate, prop):
            if tentative:
                print(f"{candidate.__name__} is missing the {prop} attribute")
                return False
            else:
                raise AttributeError(f"{candidate.__name__} is missing the {prop} attribute")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if isinstance(iface, str):
        iface = getClass(iface)
    if isinstance(candidate, str):
        candidate = getClass(candidate)
    if tentative:
        if hasattr(candidate, "provides"):
            return iface in candidate.provides
        return False
    else:
        return isinstance(candidate, iface)

def determineMetaclass(bases, explicit_mc=None):

    if explicit_mc is not None:
        return explicit_mc

    metaclasses = []
    for b in bases:
        if hasattr(b, "__metaclass__"):
            metaclasses.append(b.__metaclass__)

    if len(metaclasses) > 1:
        raise ValueError("Multiple conflicting __metaclass__ objects in bases")

    return metaclasses[0] if metaclasses else type

