def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """

        required_fields = [cls.FIN_NO, cls.PRODUCT_CATEGORY, cls.PRODUCT_SUBCATEGORY, cls.POLICY_NUMBER]
        optional_fields = [cls.BRAND_NAME, cls.DEALER_NAME, cls.MODEL_DETAIL, cls.FAILED_PART_NUMBER, cls.SERVICE_CODE, cls.SERVICE_DATE, cls.SERVICE_DATE_FIELD]
        valid_fields = required_fields + optional_fields

        if yaml_file is None:
            yaml_file = cls.RELEASE_PATH

        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)

        for field in valid_fields:
            if field not in data:
                raise IRValidatorException("Missing mandatory field " + field)

        if cls.FIN_NO not in data:
            raise IRValidatorException("Fin_no field missing in file")

        if cls.PRODUCT_CATEGORY not in data:
            raise IRValidatorException("Product_category field missing in file")

        if cls.PRODUCT_SUBCATEGORY not in data:
            raise IRValidatorException("Product_subcategory field missing in file")

        if cls.POLICY_NUMBER not in data:
            raise IRValidatorException("Policy number field missing in file")

        return data

def validate_from_file(cls, yaml_file):
    if yaml_file is None:
        raise ValueError("YAML file cannot be None")

    with open(yaml_file, "r", encoding="utf-8") as f:
        data = yaml.load(f, Loader=yaml.SafeLoader)

    if data is None:
        raise IRValidatorException("Could not load data from YAML file")

    missing_fields = {f: data.get(f) for f in cls.REQUIRED_FIELDS if data.get(f) is None}
    if missing_fields:
        raise IRValidatorException(f"Missing mandatory field(s) {missing_fields} in YAML file")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # This method takes a dictionary of parser dictionaries and returns a new dictionary
    # with the included groups from the original dictionaries
    new_dict = {}
    for key, value in parser_dict.items():
        new_dict[key] = {}
        # Check if the value is a list of groups to include
        if isinstance(value, list):
            # If it is, loop through the list and include the groups
            for group in value:
                if group in self.groups:
                    new_dict[key][group] = self.groups[group]
        else:
            # If it is not a list, assume it is a group to include
            if value in self.groups:
                new_dict[key][value] = self.groups[value]
    return new_dict

