def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    for arg in self.arguments:
        value = arg.default_value
        if value is not None:
            continue
        default_value = self.spec.get_default_value(arg.name)
        if default_value is None:
            continue
        if default_value == "$NAME":
            default_value = self.spec.source.name
        if default_value == "$SOURCE":
            default_value = self.spec.source.source
        arg.default_value = default_value

