    arg_types = {a.type for a in self._spec if a is not None}

    # Get the default values from the spec
    default_values = {a.default for a in self._spec if a.default is not None}

    # Get the values of any arguments that were not provided in the constructor
    init_args = {a.name for a in self._initialized_args}
    extra_args = arg_names - init_args
    for arg in extra_args:
        if arg in default_values:
            setattr(self, arg, default_values[arg])
        elif arg in arg_types:
            setattr(self, arg, arg_types[arg]())
        elif arg in self.get_class_vars():
            setattr(self, arg, getattr(self.__class__, arg))
        else:
            raise ValueError(f"Unable to determine the default value for argument {arg}.")

