    :param args: The received arguments.
    """

    # check if minimum and maximum values are set for all arguments
    for arg_name in self.arg_spec:
        arg_spec = self.arg_spec[arg_name]

        # check if minimum value is set for this argument
        if arg_spec.min is not None:
            arg_val = args[arg_name]

            # check if minimum value is valid for this argument
            if arg_val < arg_spec.min:
                raise ValueError(f"Argument {arg_name} must be greater than or equal to {arg_spec.min}")

        # check if maximum value is set for this argument
        if arg_spec.max is not None:
            arg_val = args[arg_name]

            # check if maximum value is valid for this argument
            if arg_val > arg_spec.max:
