    :param values_dict: The dict of with arguments
    """

    # Cast arguments to correct types if needed
    for arg_name, value in values_dict.items():
        if arg_name in self.NON_CLI_ARGS_TYPES and self.NON_CLI_ARGS_TYPES[arg_name] == bool:
            values_dict[arg_name] = str(value).lower() in ("true", "t", "1")
        elif arg_name in self.NON_CLI_ARGS_TYPES and self.NON_CLI_ARGS_TYPES[arg_name] == int:
            values_dict[arg_name] = int(value)
        elif arg_name in self.NON_CLI_ARGS_TYPES and self.NON_CLI_ARGS_TYPES[arg_name] == float:
            values_dict[arg_name] = float(value)

