def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for arg, value in values_dict.items():
        if value is not None:
            # If value is a boolean flag, convert it to a boolean
            if arg.startswith("--") and len(arg) > 2 and arg[2] == "-" and len(arg) > 3:
                if value.lower() == "false":
                    value = False
                elif value.lower() == "true":
                    value = True

            # If value is a digit, convert it to an integer or float
            if value.isdigit():
                try:
                    value = int(value)
                except ValueError:
                    value = float(value)

            # If value is a date/time string, convert it to a datetime object
            if arg == "--time" or arg.startswith(("--datetime", "--date")):
                value = self._parse_datetime(value)

            values_dict[arg] = value

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    result = {}

    plugin_spec = importlib.util.spec_from_file_location(plugin_dir, f"{plugin_dir}/plugin.spec")
    plugin_module = importlib.util.module_from_spec(plugin_spec)
    plugin_spec.loader.exec_module(plugin_module)

    if hasattr(plugin_module, "__entity__"):
        entity = plugin_module.__entity__
    elif hasattr(plugin_module, "Entity"):
        entity = plugin_module.Entity
    else:
        return result

    if hasattr(entity, "name"):
        name = entity.name
    else:
        name = "Plugin"

    result["name"] = name

    if hasattr(entity, "description"):
        result["description"] = entity.description

    if hasattr(entity, "version"):
        result["version"] = entity.version

    if hasattr(entity, "keywords"):
        result["keywords"] = entity.keywords

    if hasattr(entity, "properties"):
        result["properties"] = entity.properties

    if hasattr(entity, "license"):
        result["license"] = entity.license

    return result

